/**
 * 3C ONYX — Bird-Dog Referral Ledger
 * Author: Ronald Antonio Cadet — CUXTOMCANDYCLUB LLC
 *
 * Tracks every service-to-sales referral generated by a Service Node (Jim's Rims, etc.)
 * Auto-settlement fires on deal closure via Stripe Connect.
 * Trade Secret TS-05 — Automated Referral Ledger.
 */
import {
  pgTable, text, serial, integer, timestamp, pgEnum, numeric, boolean, jsonb,
} from "drizzle-orm/pg-core";
import { createInsertSchema, createSelectSchema } from "drizzle-zod";
import { z } from "zod/v4";
import { usersTable } from "./users";

export const referralStatusEnum = pgEnum("referral_status", [
  "Pending",
  "Contacted",
  "Qualified",
  "DealOpen",
  "Closed",
  "Settled",
  "Expired",
  "Voided",
]);

export const referralLedgerTable = pgTable("referral_ledger", {
  id:              serial("id").primaryKey(),
  referralId:      text("referral_id").notNull().unique(),        // e.g. REF-XJ7K22
  vin:             text("vin").notNull(),
  vehicleLabel:    text("vehicle_label"),                          // "2022 Porsche 911"
  referringNodeId: integer("referring_node_id")
                     .references(() => usersTable.id, { onDelete: "set null" }),
  referringNodeName: text("referring_node_name").notNull(),        // "Jim's Rims"
  referringNodeType: text("referring_node_type").notNull().default("ServiceNode"),
  buyerMemberId:   integer("buyer_member_id")
                     .references(() => usersTable.id, { onDelete: "set null" }),
  buyerName:       text("buyer_name"),
  status:          referralStatusEnum("status").notNull().default("Pending"),
  commissionPctBps: integer("commission_pct_bps").notNull().default(300),  // 300 bps = 3%
  dealValueUsd:    numeric("deal_value_usd", { precision: 14, scale: 2 }),
  commissionUsd:   numeric("commission_usd", { precision: 12, scale: 2 }),
  stripePayoutId:  text("stripe_payout_id"),
  settledAt:       timestamp("settled_at", { withTimezone: true }),
  closedAt:        timestamp("closed_at", { withTimezone: true }),
  notes:           text("notes"),
  metadata:        jsonb("metadata"),
  createdAt:       timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt:       timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export const insertReferralLedgerSchema = createInsertSchema(referralLedgerTable).omit({
  id: true, createdAt: true, updatedAt: true,
});
export const selectReferralLedgerSchema = createSelectSchema(referralLedgerTable);
export type InsertReferralLedger = z.infer<typeof insertReferralLedgerSchema>;
export type ReferralLedger = typeof referralLedgerTable.$inferSelect;
